update pages set contenu = '{"gabarit":"editorial","chapeau":"Un bon résultat en maintenance vient rarement de la chance : il vient d''une méthode répétable. Ces process ouvrent notre façon de travailler et prolongent le [guide maintenance industrielle](/ressources/) avec le mode d''emploi de nos interventions, étape par étape.","blocs":[]}'::jsonb where path = '/ressources/process/';
update pages set contenu = jsonb_set(contenu, '{blocs}', (contenu->'blocs') || '[{"type":"citation","texte":"Ce sont nos méthodes réelles, celles que suivent nos équipes chez plus de 120 clients. Vous pouvez les reprendre chez vous, ou nous confier leur mise en œuvre."},{"type":"titre","niveau":2,"texte":"Organiser la maintenance au quotidien","id":"organiser-la-maintenance-au-quotidien"},{"type":"paragraphe","texte":"Le préventif qui tient et l''équipe qui va avec : les deux fondations d''un service fiable."},{"type":"liste","items":[{"accroche":"Poser le préventif","texte":"Le process [gestion de la maintenance préventive](/ressources/process/gestion-maintenance-preventive/) montre comment planifier, exécuter et suivre l''entretien sans qu''il ne saute au premier coup de feu."},{"accroche":"Choisir les bons techniciens","texte":"Le process [sélection technicien de maintenance](/ressources/process/selection-des-techniciens/) détaille notre filtre, technique et comportemental, qui ne retient que 10 % des candidats."}]},{"type":"titre","niveau":2,"texte":"Sécuriser les moments critiques","id":"securiser-les-moments-critiques"},{"type":"paragraphe","texte":"Un arrêt de ligne et un chantier à risque se préparent, ils ne s''improvisent pas. Deux process pour les tenir."},{"type":"liste","items":[{"accroche":"Préparer un arrêt","texte":"Le process [préparation arrêt technique](/ressources/process/preparer-un-arret-technique/) cadre le périmètre, le planning et le redémarrage, du J-90 au retour d''expérience."},{"accroche":"Encadrer la coactivité","texte":"Le process [protocole de sécurité](/ressources/process/protocole-de-securite/) pose le plan de prévention et l''accueil des entreprises extérieures, avant d''ouvrir le chantier."}]},{"type":"titre","niveau":2,"texte":"Reprendre ou déléguer","id":"reprendre-ou-deleguer"},{"type":"paragraphe","texte":"Ces méthodes ne sont pas des secrets maison. Vous choisissez de les appliquer vous-même ou de nous en confier l''exécution."},{"type":"liste","items":[{"accroche":"Comme guide interne","texte":"Chaque process se lit comme un mode opératoire. Votre équipe s''en sert pour cadrer ses propres interventions."},{"accroche":"Comme prestation","texte":"Nos techniciens appliquent ces mêmes méthodes chez vous, du préventif à l''arrêt technique, avec les comptes rendus qui vont avec."}]},{"type":"citation","texte":"Une méthode à mettre en place, un arrêt à préparer ? Nos techniciens interviennent sur site : appelez le 04 78 33 72 05, un chargé d''affaires vous rappelle dans l''heure."},{"type":"citation","texte":"À lire aussi : [Ressources : Livres blancs](/ressources/livres-blancs/)"},{"type":"citation","texte":"[Demander un diagnostic maintenance](/contact/)"}]'::jsonb) where path = '/ressources/process/';
